package com.hbm.client.excavator;
import com.hbm.client.model.*;import com.hbm.machine.excavator.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Exact source authored mesh, crusher/drill pivots, extended shaft and flowing material chute quads. */
public final class ExcavatorRenderer implements BlockEntityRenderer<ExcavatorBlockEntity> {
 static final ResourceLocation MODEL=ExcavatorContent.id("models/machines/mining_drill.obj"),TEXTURE=ExcavatorContent.id("textures/models/machines/mining_drill.png"),COBBLE=ExcavatorContent.id("textures/models/machines/cobblestone.png"),GRAVEL=ExcavatorContent.id("textures/models/machines/gravel.png");public ExcavatorRenderer(BlockEntityRendererProvider.Context context){}
 static void all(PoseStack p,MultiBufferSource b,int light,int overlay){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyObjRenderer.renderAll(mesh,p,b.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR);}private static void part(WavefrontMesh mesh,String name,PoseStack p,MultiBufferSource b,int light,int overlay){LegacyObjRenderer.renderOnly(mesh,p,b.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR,name);}
 @Override public void render(ExcavatorBlockEntity m,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){int angle=switch(DummyableBlock.facing(m.getBlockState())){case SOUTH->0;case EAST->90;case NORTH->180;default->270;};var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyContactShadows.render(m,mesh,new org.joml.Matrix4f().translation(.5F,-3,.5F).rotateY((float)Math.toRadians(angle)),p,buffers);p.pushPose();p.translate(.5,0,.5);p.mulPose(Axis.YP.rotationDegrees(angle));p.translate(0,-3,0);part(mesh,"Main",p,buffers,light,overlay);float crusher=m.prevCrusherRotation+(m.crusherRotation-m.prevCrusherRotation)*partial;p.pushPose();p.translate(0,2,2.8125);p.mulPose(Axis.XP.rotationDegrees(-crusher));p.translate(0,-2,-2.8125);part(mesh,"Crusher1",p,buffers,light,overlay);p.popPose();p.pushPose();p.translate(0,2,2.1875);p.mulPose(Axis.XP.rotationDegrees(crusher));p.translate(0,-2,-2.1875);part(mesh,"Crusher2",p,buffers,light,overlay);p.popPose();p.pushPose();p.mulPose(Axis.YN.rotationDegrees(m.prevDrillRotation+(m.drillRotation-m.prevDrillRotation)*partial));float extension=m.prevDrillExtension+(m.drillExtension-m.prevDrillExtension)*partial;p.translate(0,-extension,0);part(mesh,"Drillbit",p,buffers,light,overlay);while(extension>=-1.5){part(mesh,"Shaft",p,buffers,light,overlay);p.translate(0,2,0);extension-=2;}p.popPose();if(m.chuteTimer>0){double u=-System.currentTimeMillis()%250D/250D;chute(p,buffers,COBBLE,.125F,.125F,3,2,1,1,u,light,overlay);boolean crushed=m.enableCrusher;chute(p,buffers,crushed?GRAVEL:COBBLE,crushed?.5F:.25F,.0625F,2,1,crushed?4:2,.5F,u,light,overlay);}p.popPose();}
 private static void chute(PoseStack p,MultiBufferSource b,ResourceLocation texture,float x,float z,float top,float bottom,float wideU,float narrowU,double v,int light,int overlay){var out=b.getBuffer(RenderType.entityCutout(texture));face(p,out,new float[][]{{x,top,2.5F+z},{-x,top,2.5F+z},{-x,bottom,2.5F+z},{x,bottom,2.5F+z}},0,0,1,wideU,v,false,light,overlay);face(p,out,new float[][]{{-x,top,2.5F-z},{x,top,2.5F-z},{x,bottom,2.5F-z},{-x,bottom,2.5F-z}},0,0,-1,wideU,v,true,light,overlay);face(p,out,new float[][]{{-x,top,2.5F+z},{-x,top,2.5F-z},{-x,bottom,2.5F-z},{-x,bottom,2.5F+z}},-1,0,0,narrowU,v,false,light,overlay);face(p,out,new float[][]{{x,top,2.5F-z},{x,top,2.5F+z},{x,bottom,2.5F+z},{x,bottom,2.5F-z}},1,0,0,narrowU,v,true,light,overlay);}
 private static void face(PoseStack p,VertexConsumer out,float[][] points,float nx,float ny,float nz,float width,double v,boolean reverse,int light,int overlay){for(int i=0;i<4;i++)out.addVertex(p.last(),points[i][0],points[i][1],points[i][2]).setColor(-1).setUv((i==0||i==3)^reverse?0:width,(float)(v+(i>=2?4:0))).setOverlay(overlay).setLight(light).setNormal(p.last(),nx,ny,nz);}
 @Override public boolean shouldRenderOffScreen(ExcavatorBlockEntity m){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(ExcavatorBlockEntity m){var p=m.getBlockPos();return new AABB(p.getX()-3,m.getLevel()==null?-64:m.getLevel().getMinBuildHeight(),p.getZ()-3,p.getX()+4,p.getY()+5,p.getZ()+4);}
}
